s=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html#Flasque de Fer&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;Flasque de Fer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;170.000 po&lt;/td&gt;&lt;td&gt;0,5 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html#Miroir de Prouesse Mentale&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;Miroir de Prouesse Mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;175.000 po&lt;/td&gt;&lt;td&gt;20 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html#Skiff volant&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;Skiff volant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;180.000 po&lt;/td&gt;&lt;td&gt;1 250 kg&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html#Miroir dEmprisonnement&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;Miroir d’Emprisonnement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;200.000 po&lt;/td&gt;&lt;td&gt;25 kg&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
