&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d’objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;servation-Des-Morts.html&quot; title=&quot;Pr&#233;servation des morts&quot;&gt;pr&#233;servation des morts&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-De-Pierre.html&quot; title=&quot;Peau de pierre&quot;&gt;peau de pierre&lt;/a&gt;&lt;/i&gt;  ; &lt;b&gt;Prix&lt;/b&gt; : 5.000 po
&lt;/div&gt;&lt;br /&gt;
