&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d’objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;g&#233;n&#233;ration-Deidolon.html&quot; title=&quot;R&#233;g&#233;n&#233;ration d&amp;#39;eidolon&quot;&gt;r&#233;g&#233;n&#233;ration d’eidolon&lt;/a&gt;&lt;/i&gt;  ; &lt;b&gt;Prix&lt;/b&gt; : 3.000 po
&lt;/div&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Issue surnaturelle&quot; href=&quot;#Issue surnaturelle&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
